pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 _changeFee) public {
        // 1. Setup: fuzz the _changeFee, ensure initialization hasn't happened yet.
        // Bound to the type range (uint56).
        _changeFee = uint56(bound(_changeFee, 0, type(uint56).max));

        // 2. Initialize with the fuzzed parameter.
        // We use fake addresses and values for the other parameters; they are irrelevant to the property.
        c.initialize(
            address(0x1),
            address(0x2),
            100,
            100,
            _changeFee,
            100, // feeRate (<=5000)
            bytes32(uint256(1)),
            false,
            false
        );

        // 3. Assert: the stored changeFee must equal the passed _changeFee.
        assertTrue(c.changeFee() == _changeFee);
    }
}

