pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // Bound feeRate to a wide admissible range.
        // The bug flips the condition: reference accepts only <= 5000, mutant accepts only > 5000.
        // We check any successful initialization leaves feeRate <= 5000.
        vm.assume(_feeRate > 0); // keep wide, just exclude 0 for interest
        vm.assume(_feeRate < 10000); // keep wide

        bool initializedOk;
        try c.initialize(
            address(0),
            address(0),
            0,
            0,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {
            initializedOk = true;
        } catch {
            initializedOk = false;
        }

        if (initializedOk) {
            // After a successful initialization, the stored feeRate must be at most 5000.
            assertTrue(c.feeRate() <= 5000);
        } else {
            // If initialization failed, we have no stored state to check.
            assertTrue(true);
        }
    }
}

